/**
 * A real-world league, tour or conference within a sport — the PGA Tour, the NBA. Never the product's League.
 */
export type SportLeagueDto = {
    /**
     * Sport league identifier.
     */
    id: string;
    /**
     * The sport this sport league belongs to.
     */
    sportId: string;
    /**
     * Sport league name, e.g. "PGA Tour".
     */
    name: string;
    /**
     * The provider's tour name for this sport league (e.g. "PGA TOUR"), or a substring its event names carry. Catalog browse keeps an event that matches either way; the event-year import (importEventYearFromProvider) needs the tour name, ignoring case. null when none is set.
     */
    matchKeyword: string | null;
    /**
     * The event year the sport league is currently on, if one is set. Always a year the sport league has events in when it was set.
     */
    currentEventYear: number | null;
    /**
     * Whether the sport league is in use; a read filter, not a write lock.
     */
    isActive: boolean;
    /**
     * How the sport league's bracket winners reach their next match: FIXED by each match's link, or RESEED_BY_SEED, where after a round whose matches link nowhere the admin places the teams left in each region, the best seed hosting the worst (the NFL). FIXED for a sport not played as a bracket.
     */
    bracketAdvancement: 'FIXED' | 'RESEED_BY_SEED';
    /**
     * What the sport league calls its bracket's rounds, first to final (the NBA: First Round, Conference Semifinals, Conference Finals, NBA Finals). Empty when the sport's round names are used. Set with the league's reference data, never by a request.
     */
    roundNames: Array<string>;
    /**
     * The periods the sport league's games are played in, when not its sport's: HALVES for men's college basketball. Null plays the sport's layout. Set with the league's reference data, never by a request.
     */
    matchPeriodLayout: 'QUARTERS' | 'HALVES' | 'THREE_PERIODS' | null;
    /**
     * The first round whose matches are single games a squares contest can be played on, when not every round's are: 5 for the Champions League, whose earlier rounds are two-legged ties, 3 for MLS, whose round one is a best-of-three series. Null when every round's matches can take one. Set with the league's reference data, never by a request.
     */
    squaresFromRound: number | null;
    /**
     * Participants currently affiliated with the sport league.
     */
    affiliationCount: number;
    /**
     * Events on record for the sport league, across every series and year.
     */
    sportEventCount: number;
    /**
     * ISO 8601 datetime string.
     */
    createdAt: string;
    /**
     * ISO 8601 datetime string.
     */
    updatedAt: string;
};

