/**
 * A round of golf scores.
 */
export type GolfRoundScoreUploadRequest = {
    rows: Array<{
        participantId?: string;
        externalId?: string;
        playerName?: string;
        /**
         * Null when only the score to par is known; such a row is not stored.
         */
        strokes: number | null;
        scoreToPar: number;
        /**
         * Holes completed in the round. A round is 18 holes; playoff holes are never scored.
         */
        thru?: number;
        status: 'IN_PROGRESS' | 'COMPLETED' | 'DNF' | 'DSQ' | 'MISSED_CUT';
        completedAt?: string;
    }>;
};

/**
 * A dry run of a golf score upload. Nothing is written.
 */
export type GolfRoundScorePreviewResponse = {
    /**
     * One per uploaded row, in upload order.
     */
    rows: Array<{
        /**
         * One golfer's result for one round. The first identifier present is used: participantId, then externalId, then an exact case-insensitive playerName, matched within the event's field.
         */
        row: {
            participantId?: string;
            externalId?: string;
            playerName?: string;
            /**
             * Null when only the score to par is known; such a row is not stored.
             */
            strokes: number | null;
            scoreToPar: number;
            /**
             * Holes completed in the round. A round is 18 holes; playoff holes are never scored.
             */
            thru?: number;
            status: 'IN_PROGRESS' | 'COMPLETED' | 'DNF' | 'DSQ' | 'MISSED_CUT';
            completedAt?: string;
        };
        /**
         * How an uploaded row resolved to a participant: one match, none, or several.
         */
        resolution: 'MATCHED' | 'UNRESOLVED' | 'AMBIGUOUS';
        /**
         * The field row it resolved to; set only when MATCHED.
         */
        sportEventParticipantId: string | null;
        participantName: string | null;
        /**
         * What applying the row would do to the golfer's stored round. SKIPPED: the row has no strokes, so applying stores nothing for it.
         */
        change: 'CREATE' | 'UPDATE' | 'UNCHANGED' | 'SKIPPED';
        /**
         * What is stored now; null when nothing is.
         */
        before: {
            strokes: number | null;
            scoreToPar: number;
            thru: number | null;
            status: 'IN_PROGRESS' | 'COMPLETED' | 'DNF' | 'DSQ' | 'MISSED_CUT';
        } | null;
        /**
         * What is stored now; null when nothing is.
         */
        after: {
            strokes: number | null;
            scoreToPar: number;
            thru: number | null;
            status: 'IN_PROGRESS' | 'COMPLETED' | 'DNF' | 'DSQ' | 'MISSED_CUT';
        } | null;
    }>;
    /**
     * Counts by resolution.
     */
    rollup: {
        total: number;
        matched: number;
        unresolved: number;
        ambiguous: number;
    };
};

/**
 * A correction to one golfer's round. Each value sent is stored exactly as sent and nothing is derived from another: to par is not computed from strokes, and completedAt is not set by a COMPLETED status. Omitted values keep what is stored.
 */
export type UpdateGolfRoundScoreRequest = {
    strokes?: number;
    scoreToPar?: number;
    /**
     * Holes completed in the round. A round is 18 holes; playoff holes are never scored. Null clears it, for a golfer who has not started.
     */
    thru?: number | null;
    status?: 'IN_PROGRESS' | 'COMPLETED' | 'DNF' | 'DSQ' | 'MISSED_CUT';
    /**
     * Null clears it.
     */
    completedAt?: string | null;
};

/**
 * A race's finishing order, or a correction to it: one row per runner named. Runners not named keep the result already stored.
 */
export type RaceResultUploadRequest = {
    /**
     * Whether the race's result is official once applied. It is set on every result of the race, sent or already stored: a race is official as a whole. Contest scoring counts results only once they are official.
     */
    isOfficial: boolean;
    rows: Array<{
        participantId?: string;
        externalId?: string;
        playerName?: string;
        /**
         * How the race ended for this runner.
         */
        resultStatus: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START';
        /**
         * Finishing place, 1 for the winner. Runners in a dead heat share a place, and the next place skips (1, 2, 2, 4). Only a FINISHED runner has one; it is required for every FINISHED runner once the result is official.
         */
        finishPosition: number | null;
        /**
         * Post position (or grid slot); null when not known.
         */
        startPosition: number | null;
        /**
         * The jockey (or rider) for this start; null when not known.
         */
        riderName: string | null;
    }>;
};

/**
 * A dry run of a race result. Nothing is written.
 */
export type RaceResultPreviewResponse = {
    /**
     * One per row sent, in the order sent.
     */
    rows: Array<{
        /**
         * One runner's result. The first identifier present is used: participantId, then externalId, then an exact case-insensitive playerName, matched within the event's field. Every value is stored exactly as sent.
         */
        row: {
            participantId?: string;
            externalId?: string;
            playerName?: string;
            /**
             * How the race ended for this runner.
             */
            resultStatus: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START';
            /**
             * Finishing place, 1 for the winner. Runners in a dead heat share a place, and the next place skips (1, 2, 2, 4). Only a FINISHED runner has one; it is required for every FINISHED runner once the result is official.
             */
            finishPosition: number | null;
            /**
             * Post position (or grid slot); null when not known.
             */
            startPosition: number | null;
            /**
             * The jockey (or rider) for this start; null when not known.
             */
            riderName: string | null;
        };
        /**
         * How an uploaded row resolved to a participant: one match, none, or several.
         */
        resolution: 'MATCHED' | 'UNRESOLVED' | 'AMBIGUOUS';
        /**
         * The field row it resolved to; set only when MATCHED.
         */
        sportEventParticipantId: string | null;
        participantName: string | null;
        /**
         * Why a resolved row cannot be applied. DUPLICATE_PARTICIPANT: another row names the same runner. POSITION_WITHOUT_FINISH: a finishing place on a runner that did not finish. FINISH_WITHOUT_POSITION: an official result for a FINISHED runner with no place.
         */
        rowError: 'DUPLICATE_PARTICIPANT' | 'POSITION_WITHOUT_FINISH' | 'FINISH_WITHOUT_POSITION' | null;
        /**
         * Null when the row cannot be applied: not MATCHED, or a row error.
         */
        change: 'CREATE' | 'UPDATE' | 'UNCHANGED' | null;
        /**
         * What is stored now; null when nothing is.
         */
        before: {
            resultStatus: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START';
            finishPosition: number | null;
            startPosition: number | null;
            riderName: string | null;
            isOfficial: boolean;
        } | null;
        /**
         * What is stored now; null when nothing is.
         */
        after: {
            resultStatus: 'FINISHED' | 'DID_NOT_FINISH' | 'DISQUALIFIED' | 'DID_NOT_START';
            finishPosition: number | null;
            startPosition: number | null;
            riderName: string | null;
            isOfficial: boolean;
        } | null;
    }>;
    /**
     * Problems with the race's result as a whole; empty when it can be applied as far as the order goes.
     */
    orderErrors: Array<'POSITIONS_INVALID' | 'FIELD_INCOMPLETE'>;
    /**
     * Counts by resolution.
     */
    rollup: {
        total: number;
        matched: number;
        unresolved: number;
        ambiguous: number;
        /**
         * Resolved rows with a row error.
         */
        invalid: number;
    };
};

/**
 * Where a match stands. COMPLETED once its result is in; CANCELLED when it was never played.
 */
export type MatchStatusDto = 'SCHEDULED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';

/**
 * One side of a match. On a neutral site HOME is the upper line of the bracket.
 */
export type MatchSideDto = 'HOME' | 'AWAY';

/**
 * Both sides' score at the end of one period of a game (#772).
 */
export type SportEventMatchPeriodScoreDto = {
    /**
     * 1 for the first period (quarter, in American football); never the last, whose score is the match's final result.
     */
    periodNumber: number;
    /**
     * The home side's score at the end of the period, earlier periods included, as the scoreboard shows it.
     */
    homeScore: number;
    /**
     * The away side's score at the end of the period, earlier periods included.
     */
    awayScore: number;
};

/**
 * One game or match of an event, which in a bracket is also a slot naming where its winner goes.
 */
export type SportEventMatchDto = {
    id: string;
    sportEventId: string;
    /**
     * The round the match is played in; its label comes from the sport definition's round labels.
     */
    roundNumber: number;
    /**
     * Unique within the event: the bracket slot and the display order.
     */
    matchNumber: number;
    /**
     * The field row on the home side; null until it is decided, such as a later round waiting on its feeder match.
     */
    homeSportEventParticipantId: string | null;
    /**
     * The field row on the away side; null until it is decided.
     */
    awaySportEventParticipantId: string | null;
    /**
     * True when neither side is at home: screens then say "vs" rather than "@".
     */
    isNeutralSite: boolean;
    /**
     * Tip-off or kickoff; null until it is announced.
     */
    scheduledDate: string | null;
    /**
     * Where a match stands. COMPLETED once its result is in; CANCELLED when it was never played.
     */
    status: 'SCHEDULED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
    /**
     * Who won; null until the match is COMPLETED. A COMPLETED match with none is a tie (#792), which only a game of a week, never a bracket match, can be.
     */
    winnerSide: 'HOME' | 'AWAY' | null;
    /**
     * The home side's score; in a series, games won.
     */
    homeScore: number | null;
    /**
     * The away side's score; in a series, games won.
     */
    awayScore: number | null;
    /**
     * The home side's kicks scored in the shoot-out that settled a knockout match level after extra time; null with the away side's when there was none. Not part of the match score.
     */
    homeShootoutScore: number | null;
    /**
     * The away side's kicks scored in the shoot-out; null with the home side's.
     */
    awayShootoutScore: number | null;
    /**
     * The match the winner moves on to; null for the final.
     */
    advancesToMatchId: string | null;
    /**
     * The side of that match the winner fills; null for the final.
     */
    advancesToSide: 'HOME' | 'AWAY' | null;
    /**
     * The region or conference the match is played in ("AFC", "East"); null when the bracket has none. In a reseeded round each team stays in its region.
     */
    regionLabel: string | null;
    /**
     * The points spread from the home team's side (#720): -3.5 has the home team favoured by 3.5, +3.5 has it getting 3.5. Null until set. A pick'em contest scored against the spread reads it.
     */
    homeSpread: number | null;
    /**
     * The score at the end of each period entered so far, in period order; empty for a sport whose games keep no score by period. The final score is homeScore and awayScore.
     */
    periodScores: Array<{
        /**
         * 1 for the first period (quarter, in American football); never the last, whose score is the match's final result.
         */
        periodNumber: number;
        /**
         * The home side's score at the end of the period, earlier periods included, as the scoreboard shows it.
         */
        homeScore: number;
        /**
         * The away side's score at the end of the period, earlier periods included.
         */
        awayScore: number;
    }>;
};

